ALTER TABLE public.gyms ADD COLUMN deleted_at timestamptz;
ALTER TABLE public.profiles ADD COLUMN disabled_at timestamptz;
CREATE TABLE public.platform_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), whatsapp text NOT NULL DEFAULT '');
GRANT SELECT ON public.platform_settings TO authenticated;
GRANT ALL ON public.platform_settings TO service_role;
ALTER TABLE public.platform_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY platform_settings_read ON public.platform_settings FOR SELECT TO authenticated USING (true);
CREATE OR REPLACE FUNCTION public.otp_verified() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND disabled_at IS NULL) $$;
CREATE OR REPLACE FUNCTION public.is_super_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.otp_verified() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='super_admin') $$;
CREATE FUNCTION public.gym_operational(g uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.otp_verified() AND EXISTS(SELECT 1 FROM public.gyms x JOIN public.profiles p ON p.id=x.owner_id WHERE x.id=g AND x.deleted_at IS NULL AND x.frozen_at IS NULL AND p.disabled_at IS NULL AND (NOT EXISTS(SELECT 1 FROM public.owner_requests r WHERE r.gym_id=g) OR EXISTS(SELECT 1 FROM public.owner_requests r WHERE r.gym_id=g AND (r.status='Approved' OR (r.status='Pending' AND r.trial_started_at IS NOT NULL AND now()<r.trial_started_at+interval '1 hour'))))) $$;
REVOKE ALL ON FUNCTION public.gym_operational(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.gym_operational(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.gym_access(g uuid, area text DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.gym_operational(g) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND gym_id=g AND (area IS NULL OR role='Owner' OR (role!='Client' AND area=ANY(permissions)))) $$;
CREATE OR REPLACE FUNCTION public.client_has_gym_approval(g uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.gym_operational(g) AND (EXISTS(SELECT 1 FROM public.gym_records WHERE gym_id=g AND kind='members' AND client_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.user_roles WHERE gym_id=g AND user_id=auth.uid() AND role!='Client')) $$;
ALTER POLICY gym_record_read ON public.gym_records USING (public.gym_operational(gym_id) AND (public.gym_access(gym_id,CASE kind WHEN 'members' THEN 'Members' WHEN 'plans' THEN 'Members' WHEN 'sessions' THEN 'Sessions' WHEN 'attendance' THEN 'Attendance' WHEN 'staffAttendance' THEN 'Attendance' WHEN 'workouts' THEN 'Workout programs' WHEN 'gym' THEN 'Settings' ELSE 'Finance' END) OR client_id=auth.uid() OR (kind IN ('gym','workouts') AND public.gym_access(gym_id))));
ALTER POLICY own_profile_update ON public.profiles USING(id=auth.uid() AND public.otp_verified()) WITH CHECK(id=auth.uid() AND public.otp_verified());
ALTER POLICY own_roles ON public.user_roles USING(public.otp_verified() AND (user_id=auth.uid() OR public.gym_access(gym_id,'Settings') OR public.is_super_admin()));
ALTER POLICY invitations_read ON public.staff_invitations USING(public.gym_operational(gym_id) AND (public.gym_access(gym_id,'Settings') OR lower(email)=lower(auth.jwt()->>'email')));
ALTER POLICY gym_owner_events_read ON public.gym_owner_events USING(public.gym_access(gym_id,'Settings'));
CREATE OR REPLACE FUNCTION public.client_gym_directory() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',g.id,'name',g.name,'location',coalesce(r.data->>'location',''),'image',coalesce(r.data->>'cover',''),'description',coalesce(r.data->>'description',''))),'[]'::jsonb) FROM public.gyms g LEFT JOIN public.gym_records r ON r.gym_id=g.id AND r.kind='gym' WHERE public.gym_operational(g.id) $$;
CREATE OR REPLACE FUNCTION public.can_read_image(path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.otp_verified() AND (split_part(path,'/',1)=auth.uid()::text OR EXISTS(SELECT 1 FROM public.client_programs p WHERE p.user_id=auth.uid() AND p.definition::text LIKE '%'||path||'%') OR EXISTS(SELECT 1 FROM public.gym_records r WHERE public.gym_operational(r.gym_id) AND r.data::text LIKE '%'||path||'%' AND (public.gym_access(r.gym_id) OR r.kind='gym' OR public.client_has_gym_approval(r.gym_id)))) $$;
CREATE OR REPLACE FUNCTION public.respond_invitation(invitation_id uuid, accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.staff_invitations; BEGIN SELECT * INTO i FROM public.staff_invitations WHERE id=invitation_id FOR UPDATE; IF NOT public.gym_operational(i.gym_id) OR i.id IS NULL OR i.status!='Pending' OR i.expires_at<=now() OR lower(i.email)!=lower(auth.jwt()->>'email') THEN RAISE EXCEPTION 'Invitation unavailable'; END IF; IF accept THEN INSERT INTO public.user_roles(user_id,gym_id,role,permissions) VALUES(auth.uid(),i.gym_id,i.role,i.permissions) ON CONFLICT(user_id,gym_id) DO NOTHING; END IF; UPDATE public.staff_invitations SET status=CASE WHEN accept THEN 'Accepted' ELSE 'Declined' END,accepted_by=auth.uid() WHERE id=i.id; END $$;
CREATE OR REPLACE FUNCTION public.owner_gate_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.owner_requests; g public.gyms; BEGIN SELECT * INTO r FROM public.owner_requests WHERE user_id=auth.uid() ORDER BY created_at DESC LIMIT 1; SELECT * INTO g FROM public.gyms WHERE id=r.gym_id; IF g.id IS NULL THEN SELECT * INTO g FROM public.gyms WHERE owner_id=auth.uid() ORDER BY created_at LIMIT 1; END IF; RETURN jsonb_build_object('gymId',g.id,'deleted',g.deleted_at IS NOT NULL OR EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND disabled_at IS NOT NULL),'frozen',g.frozen_at IS NOT NULL,'freezeNote',coalesce(g.freeze_note,''),'requestStatus',r.status,'plan',r.plan,'gymName',coalesce(g.name,r.gym_name),'trialStartedAt',r.trial_started_at,'trialEndsAt',r.trial_started_at+interval '1 hour','now',now()); END $$;
CREATE OR REPLACE FUNCTION public.start_owner_trial() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.owner_requests; g uuid; BEGIN IF NOT public.otp_verified() THEN RAISE EXCEPTION 'Account unavailable'; END IF; SELECT * INTO r FROM public.owner_requests WHERE user_id=auth.uid() FOR UPDATE; IF r.id IS NULL OR r.status!='Pending' THEN RAISE EXCEPTION 'A pending request is required'; END IF; IF r.trial_started_at IS NOT NULL THEN RETURN public.owner_gate_state(); END IF; IF EXISTS(SELECT 1 FROM public.gyms WHERE owner_id=auth.uid()) THEN RAISE EXCEPTION 'Existing gym accounts cannot start another trial'; END IF; INSERT INTO public.gyms(name,owner_id) VALUES(r.gym_name,r.user_id) RETURNING id INTO g; INSERT INTO public.user_roles(user_id,gym_id,role,permissions) VALUES(r.user_id,g,'Owner',ARRAY['Members','Attendance','Sessions','Finance','Workout programs','Settings']); UPDATE public.owner_requests SET trial_started_at=now(),gym_id=g WHERE id=r.id; RETURN public.owner_gate_state(); END $$;
CREATE OR REPLACE FUNCTION public.decide_owner_request(request_id uuid, approve boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.owner_requests; g uuid; BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT * INTO r FROM public.owner_requests WHERE id=request_id FOR UPDATE; IF r.id IS NULL OR r.status NOT IN ('Pending','Rejected') OR EXISTS(SELECT 1 FROM public.profiles WHERE id=r.user_id AND disabled_at IS NOT NULL) OR EXISTS(SELECT 1 FROM public.gyms WHERE id=r.gym_id AND deleted_at IS NOT NULL) THEN RAISE EXCEPTION 'Request unavailable'; END IF; g=r.gym_id; IF approve THEN IF g IS NULL THEN INSERT INTO public.gyms(name,owner_id) VALUES(r.gym_name,r.user_id) RETURNING id INTO g; END IF; IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=r.user_id AND gym_id=g AND role='Owner') THEN INSERT INTO public.user_roles(user_id,gym_id,role,permissions) VALUES(r.user_id,g,'Owner',ARRAY['Members','Attendance','Sessions','Finance','Workout programs','Settings']); END IF; END IF; UPDATE public.owner_requests SET status=CASE WHEN approve THEN 'Approved' ELSE 'Rejected' END,decision_by=auth.uid(),decided_at=now(),gym_id=g WHERE id=r.id; RETURN g; END $$;
CREATE OR REPLACE FUNCTION public.set_gym_frozen(g uuid,frozen boolean,note text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF; UPDATE public.gyms SET frozen_at=CASE WHEN frozen THEN now() ELSE NULL END,freeze_note=CASE WHEN frozen THEN left(coalesce(note,''),1000) ELSE '' END WHERE id=g AND deleted_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Gym unavailable'; END IF; END $$;
CREATE FUNCTION public.disable_gym_account(g uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x public.gyms; dedicated boolean; BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT * INTO x FROM public.gyms WHERE id=g FOR UPDATE; IF x.id IS NULL THEN RAISE EXCEPTION 'Gym unavailable'; END IF; dedicated:=EXISTS(SELECT 1 FROM public.profiles WHERE id=x.owner_id AND account_type='owner') AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=x.owner_id AND (role='super_admin' OR (gym_id IS DISTINCT FROM g AND role!='Client'))) AND NOT EXISTS(SELECT 1 FROM public.gyms WHERE owner_id=x.owner_id AND id!=g AND deleted_at IS NULL); UPDATE public.gyms SET deleted_at=coalesce(deleted_at,now()) WHERE id=g; IF dedicated THEN UPDATE public.profiles SET disabled_at=coalesce(disabled_at,now()) WHERE id=x.owner_id; END IF; DELETE FROM public.client_gym_links WHERE gym_id=g; UPDATE public.staff_invitations SET status='Cancelled' WHERE gym_id=g AND status='Pending'; UPDATE public.owner_requests SET status='Rejected',decided_at=now(),decision_by=auth.uid() WHERE gym_id=g; RETURN jsonb_build_object('ownerId',x.owner_id,'disableOwner',dedicated); END $$;
REVOKE ALL ON FUNCTION public.disable_gym_account(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.disable_gym_account(uuid) TO authenticated;
CREATE FUNCTION public.guard_account_lifecycle() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NEW.disabled_at IS DISTINCT FROM OLD.disabled_at THEN RAISE EXCEPTION 'Account status is administrator managed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER profile_lifecycle_guard BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_account_lifecycle();
CREATE FUNCTION public.guard_request_account() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.profiles WHERE id=NEW.user_id AND disabled_at IS NOT NULL) THEN RAISE EXCEPTION 'Account disabled'; END IF; RETURN NEW; END $$;
CREATE TRIGGER request_disabled_account BEFORE INSERT ON public.owner_requests FOR EACH ROW EXECUTE FUNCTION public.guard_request_account();